-- lyric previews from LRCLIB (scripts/fetch-previews.mjs). Safe to re-run; never overwrites an existing preview.
alter table public.songs add column if not exists preview text check (char_length(preview) <= 200);

update public.songs set preview = v.preview from (values
('co phai da qua muon mang|ung hoang phuc', 'Từng đêm trắng thao thức nằm ôm ấp kí ức về cuộc tình đã đi qua Nào ai biết ta khóc dù ta vẫn hay khóc vì cô đơn nhớ em người ơi Thà ta đã không có còn hơn có để mất một người ta đ'),
('nguoi ta noi|ung hoang phuc', 'Có một người vẫn yêu một người Vẫn đợi chờ dẫu cho người ấy không về Tháng ngày buồn, ấp ôm kỷ niệm Hát một mình, hát cho nỗi nhớ đong đầy Người ta cứ nói đừng quá yêu Người ta cứ '),
('noi nho...|ung hoang phuc', 'Bao hẹn thề giờ người đã quên hết Cất bước quay lưng ra đi không nói câu tạ từ Bỏ lại tôi một mình giữa đêm vắng Lòng nghe cô đơn lạnh giá Tôi lê bước chân qua lối yêu ngày nào Đi '),
('chang kho thuy chung|ung hoang phuc', 'Tôi yêu em và tôi chỉ biết yêu em Từ lúc ánh mắt đó chạm vào trái tim tôi Một khi yêu ai tôi sẽ yêu hết mình Từ nay tôi chỉ có mình em Tôi xin em và tôi khuyên em hãy tin tôi Vì tô'),
('chac anh thua nguoi ay|ung hoang phuc', 'Dẫu cho lâu nay em chẳng thể nói ra Nhưng anh vẫn biết em đã đổi thay rồi Tuy bên cạnh anh, em vẫn luôn mỉm cười Nhưng đó cũng chỉ là em dối lòng Em yêu người ta, yêu một người đến'),
('anh chi biet cam nin nghe tieng em khoc|ung hoang phuc', 'Mưa rồi mưa, mưa hát ru đêm buồn Con phố vắng tênh ngắm ai về trong mưa Đèn khuya đìu hiu lay lắt soi bên hè Nhòe mắt ai bao dòng lệ cay đắng Em giờ đây nơi xứ xa quê người Hạnh ph'),
('anh chi biet cam nit nghe tieng em khoc|ung hoang phuc', 'Mưa rồi mưa, mưa hát ru đêm buồn Con phố vắng tênh ngắm ai về trong mưa Đèn khuya đìu hiu lay lắt soi bên hè Nhòe mắt ai bao dòng lệ cay đắng Em giờ đây nơi xứ xa quê người Hạnh ph'),
('du anh se khong la nguoi em yeu|ung hoang phuc', 'Mùa hè trôi qua, rồi đông sẽ qua Ngày mình quen nhau còn nhớ không anh Sánh bước bên nhau dưới ánh sao lung linh Nguyện cầu được bên nhau mãi Cuộc tình đôi ta dù bao đổi thay Tình '),
('nuoc co em chon|ung hoang phuc', 'Ngày hôm nay như thế cũng có lỗi của anh Chẳng hiểu rõ ngọn ngành Để từng lời em nói, anh cứ trách người ta Chẳng hay là em dối Người mà em yêu là người khác cơ Anh chỉ là một tron'),
('neu ta con yeu nhau|ung hoang phuc', 'Nếu em còn yêu anh Hãy tin vào mối tình Anh trao em Không một ai khác oh oh oh Nếu anh còn yêu em Cớ sao lại vui đùa? Thêm bao nhiêu nhân duyên bên bao tình nhân khác Không nhớ em '),
('loi hua cho tinh yeu|ung hoang phuc', 'Em xinh như hoa trong ánh nắng ban mai Làm bao chàng trai phải ngây ngất ngóng theo Em đang nơi nao? Nơi nao mãi trên cao? Làm cho lòng anh ở bên dưới khát khao Dẫu biết thất vọng '),
('mua thuy tinh|ung hoang phuc', 'Nghe hạt mưa rơi xuống trong lòng nhói đau Ngày em ra đi mưa buốt giá trên đường khuya Vì anh nào đâu hay biết em lừa dối anh Ngày em ra đi chẳng nói một lời Và ngày đó anh nhớ chí'),
('dan ong khong duoc quen het tinh con nghia|ung hoang phuc', 'Một bước lướt qua vết thương lòng đó Cớ sao bước chân chùng bước Ngại ngùng không bước để quên đi Vì không muốn lấp đi những gì mình đã từng có chung ngày đó Tại sao phải quên? Khô'),
('nguoi thu ba|ung hoang phuc', 'Tôi không nghe, tôi không thấy Tôi không tin những gì em đang tâm lừa dối Tôi yêu em, tôi yêu em Tôi không muốn biết rằng tôi đang dần mất em Thà tự mình lừa dối bản thân, ấp ôm ti'),
('giac mo mot cuoc tinh|ung hoang phuc', 'Từ khi em đến đây trong đời Anh nghe như trái tim ngả nghiêng Nụ cười em ấm môi thơm nồng Anh nghe như giông bão trôi qua bình yên Dìu tay nhau bước trên thiên đàng Ta bên nhau đắm'),
('buon|ung hoang phuc', 'Oh yeah huh hey Từng hạt mưa rơi rơi bên hiên ôi lòng ta nhớ mong Từng ánh mắt giây phút nghẹn ngào Ngày xưa đôi ta bên nhau Bao ngất ngây tuyệt vời Nay em ra đi cho lòng ta đớn đa'),
('sau dem nay...|ung hoang phuc', 'Còn đây một đêm, ôi, một đêm bên người Em hãy khóc đi nhé, khóc trên vai anh thật nhiều Vì mai bình minh, em sẽ ra đi thật xa Em với người một đường và anh riêng đường anh Còn đêm '),
('moi nguoi mot noi|ung hoang phuc', 'Một cuộc tình vừa qua, càng theo lời hứa phôi pha, tình yêu đã có lúc của đôi ta Cớ sao giờ đây chỉ có một người, ở chân trời xa có bóng một ai kia. Rồi cuộc tình mồ côi đành nghe '),
('quen mot ngay cho vui|ung hoang phuc', 'Tình yêu kia đến thật nhanh, rồi cũng ra đi thật nhanh Mới hôm qua ta vừa quen nhau Vậy mà hôm nay đã chia xa Tình yêu chúng ta cũng phôi pha Bởi vì anh chỉ yêu trong giấc mơ hoang'),
('du chi la chiec la|pham quynh anh', 'Em nghĩ rằng tình yêu 2 đứa như 1 chiếc lá Lá xanh trong mùa hè rồi lá úa khi mùa đông Em nghĩ rằng tình yêu 2 đứa như 1 nhánh sông Nước dâng nơi đầu dòng rồi cạn khô nơi cuối dòng'),
('noi dau ban phep mau|pham quynh anh', 'Nhiều lúc giữa những con đường quen Em nhớ những kỉ niệm Hạnh phúc của chúng mình Em chợt mỉm cười vu vơ Tuy không còn anh kề bên Nhiều lúc muốn hét lên thật to Để thế giới biết rằ'),
('bui bay vao mat|pham quynh anh', 'Em phải thức bao nhiêu đêm và em phải đếm bao nhiêu canh Để thấy em luôn được nép trong vòng tay anh Mà em nào đâu khóc, bụi bay vào mắt thôi Bụi bay vào đêm trông ngóng chân ai qu'),
('vi anh la gu chi|pham quynh anh', 'Này chàng trai đôi mươi kia à Chị sẽ nói cho em nghe là Hai ta nếu mà yêu nhau thế này Thì chắc chắn sẽ lắm phong ba Bạn bè em sẽ nói thế nào? Rồi mẹ cha em sẽ nghĩ gì? Em có sẵn s'),
('noi voi nguoi den sau|pham quynh anh', 'Tôi đã từng yêu người em yêu Từng say đắm ánh mắt với nụ cười Từng tha thiết muốn ở bên cạnh anh suốt đời Chỉ khác em, tôi là người đi trước Xin em chớ đừng lo sầu vì tôi Tôi đang '),
('gui em cua qua khu|pham quynh anh', 'Em đã từng đau nhiều như thế Em đã từng cầu xin ai quay về Em đã từng mất hết tin yêu Vì sự tổn thương đã quá nhiều Em chẳng còn vui nhiều như thế Em đã từng khóc nhiều như thế Em '),
('nguoi ta xin em buong tay|pham quynh anh', 'Ngày hôm qua em gặp cô ấy đôi mắt long lanh và đen láy Mái tóc buông dịu dàng bên vai cô ấy cho em xem thư tình Thì ra lâu nay anh vẫn thường ghé thăm và yêu thương lắm Người ta xi'),
('khi man dem ruc sang|pham quynh anh', 'Tựa như những ánh sao trời lượn bay ở khắp muôn nơi Màn đêm buông là lúc em cất lời Vì sao sáng nhất đêm nay là em giữa thế gian này Tại sao em lại đắm say như vậy? Có lẽ đi qua ba'),
('tu lau nuoc mat|mr. siro', 'Mỗi người mỗi số phận, không ai giống ai Những tình yêu chỉ một kết thúc giống nhau Lúc ban đầu hạnh phúc thường đong đầy Rồi khi gục ngã, phải tự lau nước mắt Hoá ra bên nhau lâu '),
('duoi nhung con mua|mr. siro', 'Trời trắng xoá màu mưa Mọi thứ đang lu mờ quá nhanh Phố vắng ướt nhoà Đã khắc sâu hơn những nỗi buồn Nhận ra ngần ấy năm, em vẫn không thuộc về anh Anh đã có tất cả nhưng tim em th'),
('mot buoc yeu van dam dau|mr. siro', 'Một thế giới hư ảo, nhưng thật ấm áp Em xuất hiện khiến những băng giá đời anh bỗng dần tan đi Cuộc đời anh đặt tên là muộn phiền nên làm sao dám mơ mình may mắn Được trọn vẹn cùng'),
('lang le ton thuong|mr. siro', 'Vậy mà em vẫn cứ ngây thơ Giờ đây em có vui đâu Vậy mà em vẫn cứ ngây thơ Tại sao chúng mình không nhận ra nhau sớm hơn Để anh có thể mạnh mẽ đến gần em Và thì thầm lời hứa em sẽ k'),
('song co khuc nguoi co luc|mr. siro', 'Kho tàng anh quý giá, giới hạn trong từ ngữ Không thể lột tả Sống mà như không sống, giống như một kẻ ngốc Trước khi em đến Giày vẫn ướt, anh đã xuyên qua giá lạnh mưa gió Rét buốt'),
('canh dong yeu thuong|mr. siro', 'Lời sắp nói chắc sẽ đau lòng phải không em Anh vẫn còn nhiều hoang mang vì chưa tin tình mình sẽ mất Buồn ngỡ ngàng xa em trái tim thêm lạnh Chiều nắng tàn theo hơi ấm khi giã từ N'),
('anh se manh me yeu em|mr. siro', 'Huh huh Đêm khuya vẫn trằn trọc Tinh mơ vẫn thần thờ Vậy cho đến bao giờ Xa như sao trên trời Tâm can anh rối bời Làm sao để có em (Tại sao lại nhớ đến như vậy) Ngày qua ngày tinh '),
('yeu nguoi khong the yeu|mr. siro', 'Anh thấy nhớ em Không biết từ khi nào Mà hình bóng, nụ cười ấy Luôn trong tâm trí anh Chỉ một lần anh lỡ nhìn Vào tận sâu trong mắt em Làm cho nhịp tim anh như vội hơn Trái tim anh'),
('tieng set trong anh|mr. siro', 'Nhớ hôm đầu hẹn nhau Bối rối em nhìn anh Oh no khi em mỉm cười, tim anh rụng rời Phải làm sao để anh nói với em tình cảm của anh rằng Kể từ lần đầu gặp em Mình tình cờ chạm mặt nha'),
('giac mo cua anh|mr. siro', 'Hôm qua anh mơ đến lúc mình hẹn nhau Lầu đầu tiên em đã lúng túng lúc tay chạm Những giây phút lặng yên quá khiến anh lo Dạo qua ngần ấy bao con phố vẫn chẳng nên lời Bỗng ở đâu mộ'),
('khong muon yeu lai cang say dam|mr. siro', 'Thả trôi vào những giấc mơ Nhìn ai bước cùng ai xé lòng Người không cảm động, đành để tan vỡ Buông giấc mơ lên trời Vì đôi mắt trong veo ai kia làm nhớ thương Một cảm giác ấm áp an'),
('dung lo anh doi ma|mr. siro', 'Tạm biệt em đã lâu, sắp về đến nhà Mà trong anh còn nguyên bao sâu lắng Nhà anh không thật xa, mới đây mà anh đã thấy Trống vắng tương tư, bởi vì em là huh-huh-huh-huh (Oh sah-la-l'),
('anh buoc ra tu manga|mr. siro', 'Chiếc đồng hồ đeo tay loạn nhịp tim khi em sát bên Chưa lần nào hai ta lại gần đến thế Mắt em nhìn anh Hiện ra thế giới y chang trong truyện tranh Anh thả mình tỏng mơ hoài vì tron'),
('phai chi luc truoc anh sai|mr. siro', 'Ngày mai em nói sẽ xa căn phòng này Nhìn theo con sóng biết bao nhiêu ngày rồi ngồi đây với em Người từng đã nói, "em chỉ cần sống gần anh" Lời nói ấy còn đó nhưng trong em dường n'),
('anh chi la nguoi thay the|mr. siro', 'You''re not my girl Sự thật anh không còn tin em Chẳng còn muốn nghe lời phân trần của em Goodbye, my girl! Nhìn lại những tháng ngày bên nhau Mà anh nghĩ chúng ta đã từng rất vui D'),
('phai giu em the nao|mr. siro', 'Nhớ về một thời yêu là chuỗi kí ức êm đềm cùng em Một hạnh phúc lâu dài Mới ngày nào nhìn lại tháng năm bên nhau đậm sâu Có một điều anh không ngờ đến Em (em) gạt đi hết những yêu '),
('tinh yeu dep nhat|mr. siro', 'Nhìn đồng hồ quay mà ký ức cứ cuốn mãi trong cơn say Phải chi em đang trước mặt anh lúc này Như chưa từng rời xa anh Chẳng muốn đêm mơ ác mộng lần nào nữa Chẳng biết em quên anh th'),
('tinh yeu chap va|mr. siro', 'Muốn đi xa nơi yêu thương mình từng có Để không nghe thấy giọng nói của em bên cạnh Chẳng mong cơ hội làm lại một lần nữa Thờ ơ mặc cho nước mắt em tuôn vô bờ Đừng mong cơ hội nữa '),
('thoi han cua tinh yeu|mr. siro', 'Lìa xa, nhớ lắm nhưng không thể Mình phải rời xa Tim anh đau nhói Làm sao có thể như ban đầu Tình mình chỉ đến đây thôi Em xin dừng lại Và em muốn yên tĩnh một mình Từng giọt nước '),
('nguoi nhu chung ta|mr. siro', 'Người như chúng ta được định sẵn là không thể có tình yêu Người như chúng ta tẻ nhạt đơn điệu, ốm bệnh ai bận tâm Người tôi thương đang đơn phương, nước mắt đang lăn dài thê lương '),
('nguoi con gai anh khong the quen|mr. siro', 'Anh sẽ đón em Trong giấc mơ của ngày xưa Ước gì tình mình chưa tan anh không thể quên một người Mà đã có quá nhiều điều để nhớ Những cuộc tình về sau luôn làm tim anh đau Vì anh kh'),
('nguoi xa que nho|mr. siro', 'Một buổi sáng đầu tiên ở nơi rất xa nhà Mọi người hối hả, tôi lại nguyên những ngỡ ngàng Rồi hòa với những lo toan quên tuổi trẻ Tôi từng đầy ắp bạn bè Đặt hết hy vọng, ai cũng mon'),
('song trong noi nho|mr. siro', 'Giật mình thức giấc mà không có em bên cạnh Vội gọi tên em mà không nhớ hôm qua mình chia tay Vẫn còn những thói quen xưa bởi vì anh không thể chấp nhận Hai chúng ta xa nhau rồi Từ'),
('me hieu con khong|mr. siro', 'Lại rồi ơi yêu mẹ sợ mẹ chuột tuột nào Con lỡ lời buồn biết bao Mẹ hiểu con không? Gió luôn thời con bắt đầu Không than thở chẳng nát gổ Khó khăn chẳng ai gánh nổ Lệ nhoà những gió'),
('co don khong muon ve nha|mr. siro', 'Hôm nay thật khác, tinh mơ tôi thức dậy thật sớm Cuộn mền và gối, vươn vai để lấy hơi thật sâu Giờ đi đâu cũng thấy đông người, đến lúc chỉ mong sống xa thành phố Tìm về nơi hoang '),
('co le anh chua tung|only c', 'Bao nhiêu ngày trôi mà nỗi đau y nguyên như vậy Thà rằng con tim tôi đã học làm quen với cô đơn Em như màn đêm tìm đến mỗi lúc mệt nhoài Màn đêm trôi qua với tiếng mưa vẫn chưa vơi'),
('khong the cung nhau suot kiep|mr. siro', 'Tình đã qua lâu nhưng ta cứ sống trong quá khứ Chứ có quên được đâu Chuyện buồn đôi ta đã hết, sao chẳng thể hết tàn tạ? Chỉ vì cố quên một người Mà dằn vặt đến nỗi thâm tâm không '),
('quan trong la than thai|only c', 'Quan trọng phải là thần thái Quan trọng khi là con gái Bao giờ yêu thì luôn đúng chẳng bao giờ thấy sai Quan trọng vẫn là thần thái Khi mình yêu là con trai Dẫu người ta gọi mình á'),
('nguoi dang thuong la anh|only c', 'Mỗi khi em buồn, hãy cứ khóc, anh nghe mà Người anh yêu từng chẳng yếu đuối thế này đâu Có người từng nói, "Càng yêu lâu lại càng đau" Ừ thì đúng hết, chỉ khác một điều Chúng ta ch'),
('anh khong doi qua|only c', 'Only C, boy bánh bèo Karik, boy nhà nghèo Yo! Anh này đẹp trai này, đại gia này Nhà giàu tiền tiêu thả ga Xây riêng hồ bơi để nuôi cá (uh-ooh-ooh-ooh) Còn anh thì nghèo khó, tiền c'),
('sau lung anh se la|only c', 'Midside Only C, yeah Tình yêu anh dành cho em Lâu nay không cho em yên vui thật sao? Để bây giờ thấy ánh mắt Cứ cố giấu đi anh đã thấy những gì Chỉ vì anh luôn tin Cứ ngỡ nước mắt '),
('gia nhu anh lang im|only c', 'Yêu mỗi em thôi Và mãi yêu, chỉ mỗi em trong đời Anh rất yêu em Như anh đã nói Anh yêu em nhiều lắm và anh đã nói cho em nghe là Bao yêu thương say đắm không như gió mây thoáng qua'),
('tam biet em|only c', 'Vẽ lấy cánh tay vẫn đang nắm chặt Vẽ những vết son trên môi Vẽ tiếp những lúc ta bên nhau bước về mỗi lúc đêm trôi Vẽ lấy khóe môi em đang mỉm cười Bỗng phút chốc cuốn theo môi ai '),
